export function reasoningReader(link){
 const parts=[],scenes=reasoningScenes(),add=(id,body)=>parts.push(section(id,reasoningSections.find(x=>x[0]===id)[1],body));
 const related=(s,t)=>"<a href='"+link(s)+"'>"+t+"</a>";
 add("system",p("A reasoning system spends computation to produce, inspect and choose an answer. The model supplies proposals. A generation policy decides how many proposals to produce. A verifier or selection rule decides what evidence counts. The evaluator measures whether the whole procedure works.")+"<figure class=\"transformer-flow\"><ol><li>Model proposes</li><li>Generation policy allocates attempts</li><li>Verifier checks evidence</li><li>Selection or reward uses that evidence</li><li>Evaluator measures the complete procedure</li></ol><figcaption>A conceptual system flow, not an arithmetic identity. Longer traces spend computation; they do not establish correctness.</figcaption></figure>"+p("Here a reasoning model operationally generates intermediate problem-solving tokens before a final answer. Those tokens can support decomposition, checking and repair. They do not establish that every written step caused the answer, or that the model reasons like a human.")+p("This note follows one implementation chain: measure reliably, improve inference, update the policy, transfer useful behavior, then control its cost. Each stage depends on the previous contract. More sophisticated training cannot compensate for a verifier that consistently rewards the wrong result."));
 add("from-scratch",p("Sebastian Raschka's book starts from pretrained open Qwen3 weights. It does not pretrain a model from random initialization. Building from scratch means implementing the reasoning machinery directly instead of hiding it behind a post-training framework.")+p("The implementation includes autoregressive generation, key/value caching, answer extraction, sampling, scoring, refinement, rollouts, rewards, group-relative advantages, policy gradients, stabilization and teacher-trace distillation. The 0.6B model makes these dependencies inspectable on modest hardware.")+p("Pretraining supplies knowledge and basic operations. Inference procedures elicit and select behavior. Post-training changes the distribution of that behavior. These roles overlap in their effects, but they have different data, compute and evaluation contracts. "+cite(bookURL,"Build a Reasoning Model (From Scratch)")+" and its "+cite("https://github.com/rasbt/reasoning-from-scratch","companion implementation")+" provide the worked context."));
 add("pipeline",table("One pipeline, reusable operations",["Stage","Operation","Reused primitive"],[["Baseline","Generate and record an answer","Tokenizer, template, sampler and KV cache"],["Evaluation","Extract, normalize and compare","Final-answer parser and verifier"],["Inference allocation","Sample, vote or repair","Generation, answer grouping and response scoring"],["RLVR","Reward student rollouts and update","Verifier, response mask and differentiable log probabilities"],["Stabilization","Monitor and constrain updates","Checkpoint evaluation, ratios, entropy and length"],["Distillation","Collect and imitate useful teacher traces","Generation, filtering, templates and target masks"]])+p("Answer extraction first measures accuracy, then supplies a reward and filters teacher examples. Token log probabilities first score responses, then enter a policy loss. Reusing code is useful only when the contract remains explicit: an inference score is not automatically a calibrated verifier.")+p("Build and test each operation independently. A change to the parser can change reward without changing the model. A template change can change generation without changing the optimizer. Record both in experiment provenance."));
 add("evaluation-split",p("Establish a reproducible greedy baseline before introducing sampling or training. Freeze prompts, answer rules, token limits, checkpoint, seed and decoding settings. Store the raw response alongside the extracted answer and the correctness decision.")+p("The book uses MATH-500 as a held-out benchmark and non-overlapping MATH problems for training and distillation. Split by underlying problem, not just row or response. Several traces from one question are not independent evaluation questions.")+p("Repeated checkpoint selection can overfit a validation set even without gradient updates on that set. Keep a final test set outside model and hyperparameter selection. Report extraction failures separately from mathematical errors. Otherwise a cleaner wrapper can look like improved reasoning."));
 add("extraction",p("Prefer an explicit final-answer marker, such as a LaTeX boxed expression. This reference selects the last literal boxed marker. If that marker has no balanced ending, extraction fails rather than falling back to an earlier answer. Nested expressions require balanced braces; stopping at the first closing brace can truncate a fraction.")+code("def extract_last_boxed(response):\n    marker = r\"\\boxed{\"\n    start = response.rfind(marker)\n    if start < 0: return None\n    depth, escaped = 1, False\n    for end in range(start + len(marker), len(response)):\n        char = response[end]\n        if escaped: escaped = False; continue\n        if char == \"\\\\\": escaped = True; continue\n        depth += (char == \"{\") - (char == \"}\")\n        if depth == 0: return response[start + len(marker):end]\n    return None")+p("This original Python reference extracts a payload; it is not a complete LaTeX parser or a verbatim book listing. It skips escaped braces and recognizes the literal marker shown in the function. It does not interpret comments, macros or whether a marker occurs in a quoted example. Test those cases separately before using another output grammar.")+table("Keep extraction outcomes separate",["Response condition","Parser result","Next decision"],[["Nested fraction or set braces","Full balanced payload","Normalize and compare under the task contract"],["Malformed final marker after an earlier valid box","None","Record extraction failure; do not recover the earlier answer"],["Empty final box","Empty string","Reject as an empty answer; do not count it as missing syntax"],["Well-formed but incorrect expression","Extracted string","The independent checker still decides correctness"]])+p("No reference answer enters this parser. A fallback that takes the last number can extract a step index, denominator or abandoned intermediate result. If a benchmark permits a fallback, log which rule produced the answer. Parser failure should remain visible instead of being repaired with knowledge of the expected answer."));
 add("equivalence",p("Normalize superficial differences first: permitted whitespace, wrapper notation and benchmark-specific formatting. Then test exact equality. When strings differ, a symbolic checker can simplify their difference and test whether the result is zero.")+p("Surface normalization is not mathematical equivalence. The answers x and −x differ. An equation can have domain restrictions. Sets, units, intervals, root branches and ordered tuples need their own comparison rules. Do not strip signs or reorder every list merely to increase apparent accuracy.")+table("Answer-comparison procedure",["Step","Required decision"],[["Normalize permitted surface differences","Preserve signs, units, domain restrictions and answer type"],["Compare exact normalized representations","Accept when the benchmark contract makes exact equality sufficient"],["Otherwise apply a restricted symbolic comparison","Use only valid transformations under the declared domain"],["Unresolved, malformed or timed out","Do not silently label the pair equivalent"]])+p("Treat generated expressions as untrusted input. Use restricted parsing, timeouts and isolated symbolic execution where appropriate. Never execute generated code through an unrestricted evaluator. Test valid equivalent expressions, valid unequal expressions, malformed syntax and resource-intensive cases."));
 add("verifier-roles",table("The same checker has different access in different stages",["Use","Available evidence","Important boundary"],[["Benchmark measurement","Known reference or executable tests","Measures the declared held-out task"],["RL reward","Training answer or executable outcome","May be exploited by the student"],["Teacher filtering","Teacher output plus checker","Cannot establish the truth of every intermediate sentence"],["Deployment selection","Only evidence available at deployment","A hidden benchmark answer is not available by default"]])+p("On a verifiable deployment task, tests or an exact calculation may select among answers. On an ordinary unknown-answer question, a learned judge or voting rule supplies a proxy. Do not report oracle candidate coverage as deployable selection accuracy.")+p("The same bug can affect measurement, reward and teacher filtering. Agreement between these three stages is not independent confirmation when all use one faulty checker. Include hand-reviewed failures and independent tests for the verifier itself."));
 add("intermediate-compute",p("A step-by-step prompt gives a single generation more token positions in which to transform its state. The model can decompose a problem, carry intermediate quantities and reconsider an operation. This changes the generated trajectory without changing weights.")+p("The cost is sequential generation, longer context and a larger KV cache. A long trace can repeat the same error or introduce a new one. The visible number of words is only a proxy for useful computation. Compare final accuracy and latency, not length alone.")+p("Keep final-answer tokens distinct from reasoning tokens when the serving interface supports that split. A system can end reasoning yet still need enough tokens to state the result. A total-output cap and a reasoning-only cap therefore have different failure modes."));
 add("sampling",p("Parallel sampling explores several trajectories from the same prompt. Temperature and nucleus sampling change which alternatives are likely. The book suggests temperature 0.5–0.9 and top-p 0.7–0.9 as starting ranges, not universal optima.")+p("Too little diversity produces copies. Too much randomness can destroy useful structure. Fix the decoding contract while comparing sample counts, then sweep diversity separately. "+related("execution/decoding","Decoding")+" explains the logit transformation and support changes.")+p("Different seeds do not ensure independent reasoning errors. Several trajectories can share the same missing fact or attractive wrong shortcut. Answer diversity and trajectory diversity are related but not identical: distinct explanations can reach the same answer."));
 add("voting",p("Self-consistency generates N solutions, extracts their final answers, groups equivalent results and selects the most frequent group. The explanations need not use the same path. Grouping must use the same domain-aware equality contract as evaluation.")+p("Many implementations call this majority voting even when the winner has less than half the votes. That is plurality selection. State the tie rule: fixed ordering, another sample or random choice. Using the known correct answer to resolve ties turns the result into an oracle experiment.")+code("answers = [extract(sample(prompt)) for _ in range(N)]\ngroups = group_equivalent(answers, comparison_contract)\ncounts = count_valid(groups)\nreturn choose_plurality(counts, declared_tie_rule)")+p("Also declare how invalid answers contribute. Dropping parser failures changes the effective sample count. Counting them as an answer can make failure the largest group. Neither policy should be hidden."));
 add("coverage",eq(String.raw`P(\text{at least one correct in }N)=1-(1-p)^N`, "p∈[0,1] is fixed per-draw success probability; N≥1 is an integer. Draws must be independent under the same proposal distribution. This is coverage, not selected-answer accuracy.")+p("This probability describes candidate coverage, not the probability that a selector returns the correct candidate. An oracle identifies any success. Voting instead depends on how wrong answers cluster. A scorer depends on whether its ranking tracks correctness.")+scenes.sampling+p("The example fixes per-draw correctness at 40%. Splitting wrong answers helps plurality because no single wrong group receives all the remaining mass. Sharing a draw erases independence. The shared-draw parameter is a mixture probability, not a general correlation coefficient.")+p("For benchmark estimates of pass@N, distinguish the observed fraction of successful groups from a sampling estimator based on a larger pool. Keep sample dependence, seed counts and task averaging explicit."));
 add("early-stopping",p("Suppose one answer leads the next answer by m votes and r samples remain. If m &gt; r, no unseen assignment can change or tie the leader. Stopping at that point preserves the final plurality decision for the fixed sample budget.")+scenes.voting+p("The strict inequality is conservative. If m = r, the runner-up can still tie; the declared tie rule matters. At the final sample there is no work left, even when counts tie. Stopping because the leader looks convincing has a different statistical contract.")+p("Adaptive stopping may save generations, but it also changes observed runtime and the dataset of completed candidates. Record the stopping rule and compare it against the same maximum budget. A fixed-budget proof does not justify arbitrary confidence-based stopping."));
 add("proposer-verifier",p("A proposer generates candidates. An outcome reward model (ORM) scores a completed answer. A process reward model (PRM) scores intermediate states or steps, which allows pruning before full solutions finish.")+p("A PRM score need not mean that a step is logically valid. In the Snell et al. study, Monte Carlo continuation outcomes train a reward-to-go estimate. A state can receive a useful score because continuations often succeed, not because every sentence constitutes a proof.")+p("Full-solution selection can use a final-step score or aggregate step scores. These are different estimators. Multiplying scores can punish long solutions; taking a minimum emphasizes one weak step. Choose and validate the aggregation rather than treating all PRMs as the same verifier.")+p("When several candidates reach the same answer, a weighted answer vote can sum their scores. This combines proposal frequency with learned confidence. It is still a proxy unless the scoring evidence proves the result."));
 add("search",p("Step-wise beam search expands partial solutions, scores them and keeps a bounded frontier. Lookahead additionally generates future continuations before choosing which state to expand. Sequential revisions instead condition a fresh answer on earlier attempts.")+p("Search gives a scorer repeated opportunities to prefer its own systematic mistake. As the search budget grows, the selected candidate may exploit a high proxy score without becoming more correct. More scoring is not automatically more reliable verification.")+p("Count all computation: proposal tokens, discarded branches, lookahead continuations, verifier calls and context replay. A wider batch can reduce wall-clock delay while increasing work. In the Snell setup, k-step lookahead uses a budget proportional to N(k+1), not just N.")+p("Keep a held-out check independent of the search score. Track selected correctness against proxy score as budget increases. Rising score with falling accuracy is a warning about verifier over-optimization, not evidence that the model needs an even wider beam."));
 add("refinement",p("Self-refinement starts with an answer, asks for a critique and repair plan, generates a replacement, optionally accepts that replacement, then repeats. The critique must identify something repairable; generic requests to reconsider can produce an equally wrong paraphrase.")+scenes.refinement+p("The blue line tracks the current answer. The burgundy line tracks whether any answer has been correct, as if an oracle retained it. An actual scorer cannot assume that oracle. With enough damage, additional rounds reduce current correctness despite improving historical coverage.")+p("Keep answer history and acceptance decisions. Compare last-answer selection, fixed heuristic gating and an independent verifier. Do not discard the initial correct answer merely because a later response sounds more deliberate. The probabilities above are a constructed Markov model, not a measured revision curve."));
 add("confidence",eq(String.raw`\operatorname{score}(y\mid x)=\frac1T\sum_{t=1}^{T}\log\pi(y_t\mid x,y_{<t})`, "T>0 counts the scored response tokens, excluding the prompt. Positive scoring support is needed for finite logs. The exact history and chosen scoring distribution define the value; average predictability is not correctness.")+p("Sequence log probability penalizes length through additional negative terms. Averaging removes that direct sum effect, but it does not make scores calibrated across tasks or styles. A familiar wrong answer can have a higher average score than an unfamiliar correct derivation.")+p("Teacher-forced scoring needs the exact token IDs and history used for the response. Exclude prompt positions when the score is response-only. Record whether probabilities come from raw model logits or a temperature/top-p-transformed sampler; these are not the same distribution.")+p("Heuristic scorers can reward formatting, brevity or explicit checking. Those features are useful interface signals, not guarantees of truth. A judge also needs held-out calibration and resistance to persuasive but invalid explanations."));
 add("book-inference",p("The following observations come from Tables 4.1 and 5.1 of Raschka's book. The experiments use Qwen3 0.6B base/reasoning models and all 500 MATH-500 questions on DGX Spark with CUDA. Sampling in Table 4.1 uses temperature 0.9 and top-p 0.9.")+table("Table 4.1: complete inference-method observations",["Method","Model","Accuracy (%)","Total evaluation time (min)"],bookInference.map(r=>[r.method,r.model,r.accuracy.toFixed(1),r.minutes.toFixed(1)]))+p("Time is total benchmark evaluation time in this implementation, not per-request latency or a general FLOPs estimate. The 52.0% base-model vote-10 result costs 862.6 minutes. Greedy base achieves 15.2% in 10.1 minutes; step-by-step prompting achieves 40.6% in 84.5 minutes.")+p("Without step-by-step prompting, base voting at N=3,5,10 gives 29.6%, 27.8%, 31.6%. Sampling more does not produce a monotonic observed accuracy curve. Distinguish finite-benchmark variation from a universal statement about the population curve.")+table("Table 5.1: refinement rows; the greedy baselines are in Table 4.1",["Model","Acceptance scorer","Revisions","Accuracy (%)","Total evaluation time (min)"],bookRefinement.map(r=>[r.model,r.scorer,r.rounds,r.accuracy.toFixed(1),r.minutes.toFixed(1)]))+p("For the reasoning model, one unscored revision reaches 56.6%; heuristic gating reaches 57.8%; average-log-probability gating reaches 48.4%. All take about 499 minutes. These results show why confidence gating must be tested, not assumed beneficial.")+p("The tables are observations from a small-model math experiment. They do not establish rankings for every model, task, implementation or hardware configuration. "+cite(bookURL,"Book, chapters 4–5")+" contains the surrounding procedure."));
 add("search-evidence",p("Snell et al. study compute allocation using PaLM 2-S* (Codey), 12,000 MATH training problems and 500 test problems. They train task-specific verifiers and revision behavior. Their conclusions are not results for an arbitrary unchanged chat model.")+p("The study estimates difficulty using 2,048 samples per problem and divides questions into five bins. Strategy selection uses two-fold cross-validation. Difficulty-estimation overhead is mostly outside the reported generation-budget comparisons, so a practical router must account for that extra work.")+p("For PRM search, beam search can help intermediate difficulty bins but over-optimize easy questions as budget grows. The hardest bin gains little. Lookahead often underperforms at matched generation budgets. This does not support a universal rule that easy means sampling and hard means beam search.")+p("For revisions, easy questions can benefit from sequential repair; harder questions favor a mixture of parallel proposals and sequential revisions. Training supplies up to four prior answers, with older history truncated when more attempts occur. Naive revision changes about 38% of initially correct answers into incorrect ones in that setting.")+p("The study reports up to 4× fewer generation-budget units than best-of-N in selected comparisons. That is not a 4× end-to-end latency claim. "+cite(searchURL,"Scaling LLM Test-Time Compute Optimally, main §§3–8")+" separates search and revision experiments."));
 add("compute-exchange",p("Extra inference is paid per deployment request. Extra pretraining is paid once and reused across requests. Whether one replaces the other depends on deployment load, task difficulty and the model's ability to use additional computation.")+eq(String.raw`\begin{aligned}F_{\rm train}&\approx6ND_{\rm pre},&F_{\rm infer}&\approx2ND_{\rm infer}\\R&=\frac{D_{\rm infer}}{D_{\rm pre}},&K&=M+\frac{3(M-1)}R\end{aligned}`, "N>0 is the smaller model’s parameter count; M≥1 is the larger/smaller ratio. Dpre and Dinfer are positive pretraining and deployment token totals. With the same pretraining data, K is a FLOPs-matched inference-token multiplier under these approximations—not a quality or latency guarantee.")+p("Derive the expression by equating 6MNDpre + 2MNDinfer to 6NDpre + 2NKDinfer. It excludes many implementation costs and does not predict quality. Small R makes the one-time pretraining difference large relative to the deployment token budget.")+p("The study includes a roughly 14× parameter-size comparison under its FLOPs accounting. It does not establish a fixed exchange such as 2× inference replacing 10× pretraining. A useful comparison needs a matched total-compute boundary and the actual request distribution.")+p("See "+related("training/scaling","Scaling")+" for pretraining allocation. Serving must additionally measure parallelism, queueing and verifier cost; equal FLOPs do not imply equal latency."));
 add("rlvr",p("Inference allocation leaves model weights fixed. Reinforcement learning with verifiable rewards (RLVR) changes those weights using checked outcomes. Math answers, executable tests and environment states provide the reward evidence.")+eq(String.raw`A_i=\frac{r_i-\mu_r}{\sigma_r+\varepsilon},\qquad \mu_r=\frac1G\sum_{j=1}^{G}r_j`, "G≥1 responses share one prompt/opportunity. ε>0 ensures a nonzero denominator. σᵣ is a declared nonnegative group standard deviation; sample and population conventions differ.")+p("Group Relative Policy Optimization (GRPO) uses relative rewards rather than a separately trained value critic in this basic form. RLVR names the reward source; GRPO names an update method. RLVR can use other policy-gradient methods.")+p("If all rewards equal the same value, every advantage is zero. Binary all-pass and all-fail groups provide no relative correctness signal. Mixed-success tasks can provide useful contrast, but choosing only the hardest tasks can eliminate successes. Curriculum and reward granularity change this tradeoff.")+p("Additional format or process rewards can create variation even when correctness is uniform. That variation teaches the additional criterion, not new correctness evidence. "+related("post-training/rl","Reinforcement Learning")+" owns the detailed estimator and normalization choices."));
 add("training-loop",p("For each prompt, generate a group using a recorded behavior checkpoint. Extract the answer and compute reward. Freeze those rewards and advantages. Recompute response token log probabilities with gradients enabled, then form and backpropagate the update loss.")+code("responses, behavior_logp = rollout(policy, prompt, group_size)\nrewards = verify(extract(responses), reference)\nadvantages = group_normalize(rewards).detach()\ncurrent_logp = score_with_grad(policy, prompt, responses)\nsequence_logp = (current_logp * response_mask).sum(-1)\nloss = -(advantages * sequence_logp).mean()\nloss.backward()\noptimizer.step()")+p("This is conceptual pseudocode for the minimal sequence-summed update. It omits optimizer zeroing, accumulation, clipping and several production contracts. Sample generation normally runs without a gradient graph; the later scoring pass supplies differentiable probabilities.")+p("A causal language model predicts each response token from preceding context. Shift logits and targets consistently. The response mask excludes prompt and padding positions; include or exclude end markers by explicit policy. A malformed mask can train the prompt or erase all useful feedback."));
 add("objective",eq(String.raw`\mathcal L_{\rm PG}=-\frac1G\sum_{i=1}^{G}A_i\sum_{t\in\mathcal M_i}\log\pi_{\theta}(y_{i,t}\mid x,y_{i,<t})`, "G>0 is group size; 𝓜ᵢ contains retained response targets and excludes prompt/padding. Advantages and sampled histories are held fixed during the update. This sequence-summed simplified pattern is not the complete clipped/replayed GRPO objective.")+p("Summing tokens weights longer responses differently from averaging each response. Both can be implemented correctly, but they define different objectives. State the loss reduction and mask denominator. Do not call every advantage-weighted cross-entropy a complete stable GRPO system.")+p("Repeated updates on stored rollouts make the current policy differ from the behavior policy. Importance ratios and clipping address that mismatch under their assumptions. A separate reference policy provides a KL anchor. Behavior and reference are different roles even if they initially share weights.")+p("Large asynchronous training additionally needs collection versions, exact sampling probabilities, stale-trajectory handling and distributed numerical checks. The short kernel exposes the gradient mechanism; it does not replace those contracts."));
 add("book-rl",table("Table 6.1: Qwen3 0.6B, 50 update steps",["Training max tokens","Group size","MATH-500 accuracy (%)","Mean evaluation tokens"],bookRL.map(r=>[r.budget,r.group,r.accuracy.toFixed(1),r.tokens.toFixed(2)]))+p("Evaluation allows up to 2,048 generated tokens. The training maxima of 256 or 512 tokens are not the evaluation maxima. The 512-token, eight-response run reaches 47.4%, compared with the 15.2% greedy base baseline.")+p("Mean evaluation lengths are 560.22, 579.81 and 586.11 tokens for the three runs. The base and official reasoning references average 78.85 and 1,369.79 tokens in this comparison. Similar accuracy does not mean identical behavior or identical cost.")+p("Longer training can reduce held-out accuracy. Save early checkpoints and evaluate the trajectory rather than assuming the last update is best. One small-model math experiment does not establish that fifty steps suffice for arbitrary capabilities. "+cite(bookURL,"Book, chapter 6")+" supplies the educational setup."));
 add("stability",p("Track held-out accuracy alongside training reward. A growing reward can reflect exploitation of extraction rules, a narrow curriculum or a more verbose style. Track response length, entropy, reward variation, advantages, losses and policy ratios.")+table("Signals and possible interpretations",["Signal","Check next"],[["High reward, lower held-out accuracy","Reward leakage, narrow tasks, verifier shortcuts"],["Uniform rewards and zero advantages","Curriculum and reward granularity"],["Length growth without accuracy gain","Token incentives and mode conditioning"],["Entropy collapse","Exploration, update size and replay"],["Extreme ratios or loss spikes","Behavior mismatch, precision and masks"],["Early best checkpoint, later decline","Evaluate before increasing the training duration"]])+p("Clipped ratios limit a surrogate update, not every possible policy change. KL discourages drift from a reference, but can also constrain useful learning. Format rewards improve parsing, not mathematics. In the book's small experiment, adding KL did not prevent eventual collapse.")+p("These controls interact with learning rate, rollout group size, response length, reward design and prompt difficulty. Change one declared factor at a time when diagnosing failure. "+related("training/stability","Training Stability")+" adds run-level diagnosis; "+related("post-training/rl","RL")+" explains the update controls."));
 add("format",p("A verifier can reward only what it can identify. Reasoning delimiters and a predictable final-answer field make extraction and runtime parsing reliable. They are interface conventions, not evidence that the content inside is valid.")+p("Separate outcome reward from format reward. Correctly wrapping an incorrect answer should not outweigh a correct answer expressed through a recoverable interface. Conversely, deployment may require strict schemas, so correctness and schema compliance both need evaluation.")+p("Test missing delimiters, extra answers, an unfinished reasoning block and an early end-of-sequence token. Decide whether malformed output earns zero, a partial format score or a separate diagnostic. Keep that rule stable across checkpoints."));
 add("distillation",p("Hard reasoning distillation pays the teacher generation cost while collecting data. Generate traces on training prompts, verify their final answers, filter unsuitable records, apply the student's template and train on the teacher's response tokens.")+p("This supplies dense supervised targets instead of a scalar reward for an online student rollout. It can establish useful trajectories when the student rarely earns any reward. It can also copy teacher errors, unnecessary verbosity and a narrow response style.")+table("Two ways to improve the student",["Method","Target","Main cost and risk"],[["RLVR","Checked reward on student actions","Online exploration and verifier reliability"],["Hard trace distillation","Fixed teacher-generated token sequence","Teacher collection and inherited errors"]])+p("Keep prompt-family splits, source checkpoint, generation settings and filtering decisions. Verify the answer without claiming that every intermediate sentence is correct. Mask prompt/padding positions as intended; make the final answer and reasoning targets explicit.")+p("A useful sequence is teacher SFT, student RLVR, then calibrated inference allocation. It is not mandatory for every model. "+related("post-training/distillation","Distillation")+" separates fixed traces, full-distribution targets and on-policy teacher feedback."));
 add("book-distillation",table("Table 8.1: Qwen3 0.6B student distilled from two teachers",["Teacher","Epoch","Validation loss","MATH-500 accuracy (%)"],bookDistillation.map(r=>[r.teacher,r.epoch,r.loss.toFixed(4),r.accuracy.toFixed(1)]))+p("Qwen3 235B-A22B traces produce 45.0% after one epoch, then 43.8% and 44.2%. DeepSeek-R1 traces produce 30.6%, 32.4% and 33.6%. A decreasing validation loss does not always predict increasing answer accuracy.")+p("The distillation evaluation example allows up to 4,096 tokens. Do not silently treat that budget as matched to every earlier inference or RL experiment. The 48.2% official reasoning reference is useful context, not a controlled claim that these methods have equal cost.")+p("Raschka suggests that family alignment may help transfer through tokenizer, prompting conventions and response style. The teacher comparison does not isolate that cause. Teacher strength, traces, data and formatting can also differ. State family alignment as an author hypothesis, not a theorem.")+p("A small student cannot necessarily reproduce every teacher capability. Evaluate new problems and long contexts, not only training-like math. "+cite(bookURL,"Book, chapter 8")+" contains the source observations."));
 add("compute-allocation",table("Choose the first intervention from the bottleneck",["Situation","Start with","Reason"],[["Weights unavailable or no training budget","Prompting, sampling or verified refinement","Inference-only control"],["Reliable verifier and useful student successes","RLVR","Reinforce student trajectories"],["Strong teacher, limited rollout infrastructure","Verified trace distillation","Reuse teacher computation"],["Student almost never succeeds","SFT or distillation before RLVR","Establish practically reachable successes"],["Most requests are latency-sensitive","Distill and route effort","Avoid maximum generation on every request"],["Answers lack an independent check","Improve evaluation or calibrate a judge","Selection and reward share that limitation"]])+p("Account for three bills separately: teacher/data generation, training, and recurring inference. A cheaper student can amortize teacher cost over many requests. A one-off hard question may justify expensive search without any training.")+p("First sweep reproducible inference baselines. Then compare training interventions against the best relevant baseline, with token and runtime accounting. A trained model that beats greedy decoding may still be less useful than an existing inference-only configuration."));
 add("hybrid",p("A hybrid checkpoint supports concise answers and extended reasoning. The model learns what to say and how much intermediate computation to express. The two modes can have very different target lengths and stopping behavior.")+p("Explicit examples teach each mode. Evaluation must measure each mode separately: task accuracy, reasoning length, answer length, schema compliance and latency. An average across modes can hide the loss of the concise interface.")+p("If task reward consistently favors long traces, RL can make the nominal concise mode verbose. Conditional costs or distinct mode-specific training can counter that pressure. Separate instruct and reasoning checkpoints simplify some operations, but maintaining both is also a cost. Neither arrangement is universally preferable.")+p("The Smol Playbook discusses the practical interference between concise and reasoning behavior. "+related("training/practice#post-training","Staged run design")+" retains that context; "+cite("https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook","Smol Training Playbook")+" is the source."));
 add("templates",code("/think     → <think>{reasoning}</think>{answer}\n/no_think  → <think></think>{answer}")+p("These are illustrative conventions, not commands that every model understands. The model must learn the markers. The runtime must parse them consistently and distinguish intermediate output from the delivered answer.")+p("Declare whether earlier reasoning remains in multi-turn context. Stripping it changes later conditioning; retaining it changes token use and may preserve useful or misleading state. Match training and deployment where possible.")+p("An empty prefilled block can suppress the visible reasoning channel. That does not prove that the underlying network performs no internal computation. Likewise, a visible block does not prove faithful introspection. "+related("post-training/sft","SFT and Adaptation")+" owns the general template and target contract."));
 add("mode-mixture",p("Counting examples is insufficient when one concise response has 100 targets and one long trace has 2,000. The second contributes twenty times as many targets under a global token-average objective. Equal example counts need not mean equal optimization exposure.")+p("However, token count alone is not the complete answer. A per-sequence average gives each sequence a different weight from a global token average. Mode weights, sampling, padding masks and loss reduction all determine effective contribution.")+eq(String.raw`c_m=\frac{w_m\sum_{i\in\mathcal I_m}T_i}{\sum_k w_k\sum_{i\in\mathcal I_k}T_i}`, "For a globally normalized weighted token loss, cₘ is mode m’s scalar coefficient mass. 𝓘ₘ contains accepted sequences in that mode, Tᵢ counts retained targets, and wₘ≥0 is its weight. Require a positive total denominator. Per-sequence normalization gives a different mass; neither is an actual gradient-norm share.")+p("Log examples, supervised token mass and effective loss weights for each mode. Evaluate both behaviors after SFT and again after RL. Do not declare the dataset balanced merely because its row counts match."));
 add("learned-effort",p("An effort label asks for an operating point. Effort-conditioned SFT pairs labels with suitable traces. Effort-conditioned RL can make token cost depend on the label. A model does not reliably acquire these meanings from an arbitrary system instruction alone.")+eq(String.raw`R(e,y)=R_{\rm task}(y)-\lambda(e)N_{\rm tokens}(y)`, "Conceptual objective: e is requested effort, λ(e)≥0 its cost per counted token, and Ntokens(y) the declared response-token count. Real recipes may use shaping, correctness gates and extra constraints.")+scenes.effort+p("A higher token cost can prefer a shorter candidate even when its success probability is lower. A lower cost can justify more computation. The four candidates are fixed constructed points; moving the slider does not train a policy or establish a measured frontier.")+p("SFT can establish recognizable modes, while RL calibrates success and cost within them. Continuous controls require evaluation between training points, not just at named endpoints. Never invent undisclosed coefficients from a model's user-facing labels."));
 add("budget-contract",table("Three controls with different guarantees",["Control","What it changes","What it does not guarantee"],[["Soft learned effort instruction","Conditional generation behavior","An exact token ceiling"],["Template prefill or forced channel closure","Visible format and next context","A correct completed answer"],["Hard reasoning-token limit","Maximum reasoning span under the runtime rule","An answer within a total-output or latency budget"]])+p("A learned mode describes how to spend available budget. A hard limit describes how much budget is available. Combine them only after testing the interruption contract. Cutting a derivation halfway through can produce an incomplete or unsupported answer.")+p("Reserve final-answer capacity independently when required. Also count prompt replay, tool output, verifier calls and retry generations. A reasoning-token ceiling alone does not bound end-to-end work."));
 add("interrupted-training",p("Budget-aware data can truncate a reasoning trace at several points while retaining its original final answer. An externally inserted closing marker tells the runtime that the answer begins. Mask that inserted marker if it is context rather than a desired generated action.")+scenes.budget+p("The retained reasoning and answer can remain supervised targets. The inserted closure remains conditioning. At a naturally completed trace, the model-generated closure can be supervised. These are distinct masks, even when the visible string is identical.")+p("Such examples train the answer distribution after interruption. They do not guarantee successful finishing after every possible cutoff. Evaluate random and adversarial interruption points, including zero reasoning budget, incomplete calculations and traces close to natural completion."));
 add("qwen-inkling",p("Qwen3 combines long-chain-of-thought SFT, reasoning RL, thinking-mode-fusion SFT and general RL. Fusion brings thinking and non-thinking examples into one checkpoint and template. The reported inference budget can externally stop the thinking span.")+p("The effort overview describes Qwen3's partial-trace handling as emergent rather than explicitly trained through that exact interruption procedure. Do not attribute another model's masked-truncation recipe to Qwen merely because both expose a budget.")+p("Inkling uses a continuous effort value in the system message and effort-dependent per-token cost during large-scale RL. The public description does not supply every coefficient or full objective. The conceptual cost equation above explains the pattern, not a recovered private implementation.")+p(cite("https://arxiv.org/abs/2505.09388","Qwen3 technical report")+" · "+cite("https://thinkingmachines.ai/news/introducing-inkling/","Inkling release description")+" · "+cite(blogURL,"Raschka's effort synthesis")));
 add("specialists",p("DeepSeek V4 develops Non-think, Think High and Think Max specialists with mode-specific post-training settings, context and length costs. Consolidation distills their behaviors into one checkpoint. The report does not disclose every domain-to-teacher mapping.")+p("Kimi K3 similarly consolidates nine domain/effort specialists. The effort synthesis describes developing maximum-effort specialists first, then reducing budgets for high and low settings. Nine teachers does not imply every Cartesian combination of domains and effort levels.")+p("For K3's simple verifiable reasoning example, budget overrun receives −1, while correct and incorrect responses receive 1 and 0 under the stated rule. Do not apply that formula to all agentic or general tasks. Multi-teacher on-policy distillation is a separate transfer mechanism.")+p("GLM-5 describes interleaved thinking, preserved thinking and turn-level thinking. These are three context/interaction behaviors, not low/medium/high effort levels. Templates and subsequent distillation stages make the distinction operational.")+p(related("training/frontier-recipes","Frontier Recipes")+" retains architecture and full training context. "+cite("https://huggingface.co/deepseek-ai/DeepSeek-V4-Pro/blob/main/DeepSeek_V4.pdf","DeepSeek V4 report")+" · "+cite("https://github.com/MoonshotAI/Kimi-K3/blob/main/k3_tech_report.pdf","Kimi K3 report")+"; these recipe summaries follow the scoped effort synthesis, not an independent full-report replication."));
 add("nemotron",p("Nemotron 3 Ultra introduces medium-effort teacher traces in SFT, using GPT-OSS-120B as the teacher in the described recipe. About 2.5% of RL prompts receive length-aware control in math, STEM and coding. Regular, medium and off modes coexist with external budgets.")+p("Randomly truncated reasoning traces retain the final answer. An externally inserted closing marker is masked from loss, while it remains available as context. The interruption scene above isolates that mask distinction using invented lengths, not a reproduction of Nemotron's data.")+p("A learned medium mode and a hard reasoning budget can be used together, but they still need separate evaluations. Measure compliance, finishing accuracy and cost at each operating point. "+cite("https://research.nvidia.com/labs/nemotron/files/NVIDIA-Nemotron-3-Ultra-Technical-Report.pdf","Nemotron 3 Ultra report")+" is the primary source; "+cite(blogURL,"the effort overview")+" summarizes this recipe."));
 add("toggle",p("Kimi K2.5's Toggle alternates constrained and unconstrained RL periods. The constrained period encourages useful work within a problem-specific budget. The free period preserves the ability to use additional computation when it helps.")+p("The description uses lengths of correct responses to determine a budget percentile and an accuracy condition to regulate pressure. This is a training schedule, not an inference algorithm that automatically chooses each request's effort.")+p("The report describes roughly 25–30% token reduction against K2 Thinking under its comparison conditions. The number is not a universal reduction for every model or task. A lower average length must be paired with retained capability and the matched evaluation setup.")+p("Alternating phases is coherent because permanent short-budget optimization can teach the model never to explore a longer trajectory. Evaluate constrained performance and unconstrained scalability separately. "+cite("https://arxiv.org/abs/2602.02276","Kimi K2.5 report")+" · "+cite(blogURL,"effort-control synthesis")));
 add("nanbeige",eq(String.raw`\begin{aligned}b_q&=\operatorname{median}\{L:\text{historically correct rollout for }q\}\\r_i&=r_i^{\rm base}-\alpha p_q\operatorname{clip}\!\left(\frac{L_i-b_q}{L_{\max}-b_q},0,1\right)\end{aligned}`, "The historical correct set must be nonempty. bq is held fixed while pq∈[0,1] is the current group’s correctness fraction. α≥0 controls the penalty; Lmax>bq is required. Li counts response length under the same convention. This is the disclosed conditional excess-length form, not every Nanbeige reward term.")+p("Nanbeige4.2 increases the penalty when a response exceeds the historical budget and the current policy solves the problem reliably. Responses within budget receive no excess-length penalty. Low current pass rate reduces pressure, leaving more room for exploration.")+p("Historical difficulty and current competence play different roles. Recomputing the budget from the same responses would change the objective. Keep the checkpoint history used for bq separate from the group that supplies pq.")+p("The recipe alternates constrained phases with free-expansion phases where the length penalty is disabled. It therefore does not equate shorter with better under every condition. "+related("models/compact-recipes","Compact Model Recipes")+" preserves the broader Nanbeige pipeline; "+cite("https://huggingface.co/Nanbeige/Nanbeige4.2-3B/blob/main/Nanbeige42_report.pdf","Nanbeige4.2 report")+" provides the source."));
 add("limits",p("More generation can fail because the model lacks a fact, repeats a strategy, damages an already correct answer or optimizes verbosity. A hard task may need a new tool, a better proposal model or new training evidence rather than another thousand tokens.")+p("If a fixed proposal has exactly zero probability of producing a correct candidate, independent resampling cannot produce one. That statement does not cover a procedure that changes the proposal through feedback, tools or training. Softmax positivity also does not imply practical coverage of a very rare long sequence.")+p("Quality can saturate or decline with effort. Inspect failure families and length buckets, not only aggregate accuracy. Compare more samples, longer traces and stronger verification separately: these spend computation on different bottlenecks."));
 add("serving",p("Serving has two independent knobs: choose a different model, or change the inference procedure for the same weights. A smaller model at high effort may match a larger model at low effort on some tasks. That is a task-conditioned operating point, not a universal equivalence.")+table("Record an operating point with its costs",["Quantity","Why it matters"],[["Checked task quality","The intended capability"],["Reasoning and final-answer tokens","Length behavior and cost separation"],["End-to-end latency and tail latency","Sequential work, queueing and retries"],["Monetary cost","The actual deployment bill"],["Verifier/tool calls and discarded candidates","Hidden work outside delivered tokens"],["Checkpoint, mode, template and budget","Reproducible control contract"]])+p("Provider labels are not a common compute unit. High effort in one model need not equal high effort in another. Token prices are not FLOPs; FLOPs are not wall-clock time. Compare configurations on the same workload and constraints.")+p("For throughput-sensitive service, parallel candidates can increase memory pressure and reduce admission capacity. A faster isolated request can still worsen queueing for other requests. "+related("execution/serving","Serving")+" owns the scheduler and KV-cache lifecycle."));
 add("routing",p("Begin with a cheap configuration where errors are inexpensive and easy to detect. Escalate after evidence such as a failed test, an unresolved consistency check or a missing required artifact. Keep enough remaining budget for verification and delivery.")+p("Classification, extraction and routine rewrites can be good low-effort candidates, but do not route only by task name. An ambiguous extraction with high error cost differs from a routine one. Difficult coding or planning may benefit from more compute, but a missing external fact may not.")+p("An automatic router estimates benefit before it knows the answer. That estimate has its own inference and calibration cost. A model's verbal confidence is not sufficient evidence of correctness. Include a user override for latency, cost and reliability priorities.")+p("An agent can change effort across turns when its harness preserves the contract. Record the decision, failed check and remaining budget. "+related("post-training/agents","Agents and Environments")+" explains why task success depends on executable evidence, not just a persuasive final response."));
 add("experiment-contract",table("Before scaling the experiment",["Check","Required evidence"],[["Baseline","Fixed greedy setup and recorded raw responses"],["Data boundary","Disjoint train/validation/test problem families"],["Answer checker","Equivalent, unequal, malformed and adversarial tests"],["Logging","Response, extracted answer, reward, tokens and provenance together"],["Loss masks","Prompt/padding exclusion and shifted target checks"],["Group credit","Uniform rewards produce exactly zero relative advantages"],["Checkpoints","Frequent early held-out evaluation"],["Teacher data","Verified answers, deduplication and retained trace provenance"],["Effort","Separate learned modes, hard limits and interruption tests"],["Costs","Teacher, training, generation, scoring and serving boundaries"]])+p("Compare seeds or confidence intervals where feasible. MATH-500 accuracy changes in increments of 0.2 percentage points for one complete evaluation. A one-seed improvement can be real in that run without establishing a robust population ranking.")+p("The book is an educational reference, not a complete large-scale asynchronous recipe. Its small model and verifiable math domain expose mechanics clearly. Transfer to open-ended tasks requires a stronger evaluation contract, not just a larger batch."));
 add("history",table("Branches that remain useful together",["Development","What it adds","What remains unresolved"],[["Intermediate-token prompting","More sequential transformation without weight updates","Longer can still be wrong"],["Self-consistency and search","Alternative trajectories and explicit selection","Coverage differs from reliable ranking"],["RLVR and group-relative updates","Reinforce checked student behavior","Exploration, reward validity and stability"],["Teacher-trace distillation","Amortize teacher behavior in a student","Errors, mismatch and finite student capacity"],["Compute-optimal allocation, Snell et al. (2024)","Condition search/revision on difficulty","Difficulty estimation and deployment cost"],["Hybrid and effort-conditioned recipes","Multiple cost-quality behaviors in one checkpoint","Mode interference and runtime budgets"]])+p("This is a conceptual development map, not a claim that each branch replaced its predecessor. Sampling, RL and distillation can coexist in one deployed system. New reports usually refine one stage of the same pipeline."));
 add("sources",p(cite(bookURL,"Raschka: Build a Reasoning Model (From Scratch), Manning 2026")+" · "+cite("https://github.com/rasbt/reasoning-from-scratch","Companion code")+" · "+cite(searchURL,"Snell et al.: Scaling LLM Test-Time Compute Optimally")+" · "+cite(blogURL,"Raschka: Controlling Reasoning Effort in LLMs"))+p("Book tables above reproduce numerical observations with their experimental context, not licensed page images. The five interactive explanations are constructed models. They are not empirical training trajectories, measured provider curves or private training objectives.")+p(related("post-training/rl","RL")+ " · "+related("post-training/distillation","Distillation")+" · "+related("post-training/sft","SFT and Adaptation")+" · "+related("post-training/agents","Agents")+" · "+related("execution/decoding","Decoding")+" · "+related("training/scaling","Scaling")+" · "+related("training/frontier-recipes","Frontier Recipes")+" · "+related("models/compact-recipes","Compact Recipes")));
 return topic(reasoningMeta,reasoningSections,"Build a reliable measurement, spend computation where it helps, and make the resulting policy's effort controllable.",parts.join("\n"));
}
export function mountReasoning(scope=document){mountTopic(scope,reasoningMeta.slug,article=>mountReasoningScenes(article));}
reasoningMeta.searchText=reasoningReader(()=>"").replace(/<[^>]*>/g," ");
